<?php
namespace App\Controllers;
use App\Libraries\Dropdown_list;
use App\Services\Reports\SalesItemDetailReportService;
use PhpOffice\PhpSpreadsheet\Cell\DataType;
use PhpOffice\PhpSpreadsheet\Cell\Coordinate;
use PhpOffice\PhpSpreadsheet\Spreadsheet;
use PhpOffice\PhpSpreadsheet\Writer\Xlsx;
use RuntimeException;

final class Sales_item_report extends Security_Controller
{
    private const HEADERS=['Cantidad','Artículo','Tarifa','Total','ID de Remisión','Cliente','Fecha de cobro','Fecha de vencimiento','Número de IVA/GST','Estado'];
    public function __construct(){parent::__construct();$this->init_permission_checker('invoice');}
    public function index(){if(!$this->can_view_invoices())app_redirect('forbidden');$db=db_connect();$dropdown=new Dropdown_list();$data=['clients_dropdown'=>$dropdown->get_clients_id_and_text_dropdown(['blank_option_text'=>'- '.app_lang('client').' -']),'items_dropdown'=>$this->dropdown($db->table('items')->select('id,title')->where('deleted',0)->orderBy('title')->get()->getResultArray(),'item'),'payment_methods_dropdown'=>$this->dropdown($db->table('payment_methods')->select('id,title')->where(['deleted'=>0,'available_on_invoice'=>1])->orderBy('sort')->get()->getResultArray(),'payment_method'),'default_start'=>date('Y').'-01-01','default_end'=>date('Y-m-d')];return$this->template->rander('reports/sales_items/index',$data);}
    public function list_data(){if(!$this->can_view_invoices())return$this->response->setStatusCode(403)->setJSON(['error'=>'forbidden']);$options=$this->options('post');$options=append_server_side_filtering_commmon_params($options);$result=(new SalesItemDetailReportService(db_connect()))->page($options);$rows=[];foreach($result['data']as$row)$rows[]=$this->row($row);return$this->response->setJSON(['draw'=>(int)$this->request->getPost('draw'),'recordsTotal'=>$result['recordsTotal'],'recordsFiltered'=>$result['recordsFiltered'],'data'=>$rows,'summation'=>$result['summation']]);}
    public function export_csv(){return$this->export('csv');}
    public function export_excel(){return$this->export('xlsx');}
    private function export(string$type){if(!$this->can_view_invoices())app_redirect('forbidden');$query=(new SalesItemDetailReportService(db_connect()))->export($this->options('get'));$name='ventas-detalladas-articulo-'.date('Ymd-His');if($type==='csv'){$stream=fopen('php://temp','w+b');fwrite($stream,"\xEF\xBB\xBF");fputcsv($stream,self::HEADERS);while($row=$query->getUnbufferedRow())fputcsv($stream,$this->exportRow($row));rewind($stream);$body=stream_get_contents($stream);fclose($stream);return$this->response->setHeader('Content-Type','text/csv; charset=UTF-8')->setHeader('Content-Disposition','attachment; filename="'.$name.'.csv"')->setBody($body);}
        require_once APPPATH.'ThirdParty/PHPOffice-PhpSpreadsheet/vendor/autoload.php';$spreadsheet=new Spreadsheet();$sheet=$spreadsheet->getActiveSheet();$sheet->fromArray(self::HEADERS,null,'A1');$line=2;while($row=$query->getUnbufferedRow()){foreach($this->exportRow($row)as$column=>$value){$cell=$sheet->getCell(Coordinate::stringFromColumnIndex($column+1).$line);in_array($column,[0,2,3],true)?$cell->setValue((float)$value):$cell->setValueExplicit($this->safe((string)$value),DataType::TYPE_STRING);}$line++;}$sheet->setTitle('Ventas por artículo');$temp=tempnam(WRITEPATH.'cache','sales-items-');if($temp===false)throw new RuntimeException('No fue posible preparar la exportación.');try{(new Xlsx($spreadsheet))->save($temp);$body=file_get_contents($temp);if($body===false)throw new RuntimeException('No fue posible leer la exportación.');}finally{@unlink($temp);$spreadsheet->disconnectWorksheets();}return$this->response->setHeader('Content-Type','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')->setHeader('Content-Disposition','attachment; filename="'.$name.'.xlsx"')->setBody($body);}
    private function options(string$source):array{$input=fn(string$key)=>$source==='post'?$this->request->getPost($key):$this->request->getGet($key);return['start_date'=>$input('start_date'),'end_date'=>$input('end_date'),'client_id'=>$input('client_id'),'item_id'=>$input('item_id'),'payment_status'=>$input('payment_status'),'remission'=>$input('remission'),'payment_method_id'=>$input('payment_method_id'),'search_by'=>$input('search_by'),'own_creator'=>$this->show_own_invoices_only_user_id()?:0,'own_client_owner'=>$this->show_own_client_invoice_user_id()?:0];}
    private function row(object$r):array{$symbol=$r->currency_symbol?:get_setting('currency_symbol');return[$this->number($r->quantity),htmlspecialchars((string)$r->item_title,ENT_QUOTES,'UTF-8'),to_currency($r->rate,$symbol),to_currency($r->line_total,$symbol),anchor(get_uri('invoices/view/'.$r->invoice_id),htmlspecialchars($r->display_id?:get_invoice_id($r->invoice_id),ENT_QUOTES,'UTF-8')),anchor(get_uri('clients/view/'.$r->client_id),htmlspecialchars((string)$r->client_name,ENT_QUOTES,'UTF-8')),$r->collection_date?:'',(string)$r->due_date,htmlspecialchars((string)$r->vat_gst,ENT_QUOTES,'UTF-8'),$this->status((string)$r->payment_status)];}
    private function exportRow(object$r):array{return[(float)$r->quantity,$this->safe((string)$r->item_title),(float)$r->rate,(float)$r->line_total,$this->safe((string)($r->display_id?:get_invoice_id($r->invoice_id))),$this->safe((string)$r->client_name),(string)($r->collection_date??''),(string)$r->due_date,$this->safe((string)$r->vat_gst),$this->safe(app_lang($r->payment_status==='paid'?'fully_paid':$r->payment_status))];}
    private function status(string$status):string{$class=['paid'=>'bg-success','partially_paid'=>'bg-primary','credited'=>'bg-warning','not_paid'=>'bg-danger'][$status]??'bg-secondary';return"<span class='badge {$class}'>".app_lang($status==='paid'?'fully_paid':$status).'</span>';}
    private function dropdown(array$rows,string$label):string{$out=[['id'=>'','text'=>'- '.app_lang($label).' -']];foreach($rows as$row)$out[]=['id'=>(string)$row['id'],'text'=>(string)$row['title']];return json_encode($out,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
    private function number(mixed$value):string{return rtrim(rtrim(number_format((float)$value,6,'.',''), '0'),'.');}
    private function safe(string$value):string{return preg_match('/^[=+\-@]/',$value)?"'".$value:$value;}
}
